body.script:
(function () {
    'use strict';

    var DRAFT_KEY = 'obbs_intake_draft_v1';
    var form = document.getElementById('obbs_intake_form');
    var steps = [].slice.call(form.querySelectorAll('fieldset.step'));
    var inds = [].slice.call(document.querySelectorAll('.steps li'));
    var nextBtn = document.getElementById('obbs_next');
    var prevBtn = document.getElementById('obbs_prev');
    var submitBtn = document.getElementById('obbs_submit');
    var errorsBox = document.getElementById('obbs_errors');
    var errorsList = document.getElementById('obbs_errors_list');
    var index = 0;

    function show(i) {
        index = Math.max(0, Math.min(i, steps.length - 1));
        for (var j = 0; j < steps.length; j++) {
            steps[j].classList.toggle('on', j === index);
            steps[j].disabled = (j !== index);
            inds[j].classList.toggle('on', j === index);
            inds[j].classList.toggle('done', j < index);
        }
        nextBtn.classList.toggle('btn-hidden', index === steps.length - 1);
        prevBtn.classList.toggle('btn-hidden', index === 0);
        submitBtn.classList.toggle('btn-hidden', index !== steps.length - 1);
        window.scrollTo(0, 0);
    }

    function validStep(i) {
        if (steps[i].checkValidity()) { return true; }
        steps[i].reportValidity();
        return false;
    }

    function initSigPad(canvas, input, clearBtn) {
        var ctx = canvas.getContext('2d');
        var drawing = false;
        var ink = false;
        ctx.strokeStyle = '#1a2530';
        ctx.lineWidth = 2.5;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        function placeholder() {
            if (ink) { return; }
            ctx.save();
            ctx.setLineDash([6, 4]);
            ctx.strokeStyle = '#c9c9c9';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(canvas.width * 0.08, canvas.height * 0.5);
            ctx.lineTo(canvas.width * 0.92, canvas.height * 0.5);
            ctx.stroke();
            ctx.restore();
            ctx.fillStyle = '#9aa0a6';
            ctx.font = '20px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('Sign here (finger / stylus)', canvas.width / 2, canvas.height / 2);
        }

        function toPos(clientX, clientY) {
            var r = canvas.getBoundingClientRect();
            return {
                x: (clientX - r.left) * (canvas.width / r.width),
                y: (clientY - r.top) * (canvas.height / r.height)
            };
        }

        function beginStroke(clientX, clientY) {
            drawing = true;
            ink = true;
            var p = toPos(clientX, clientY);
            ctx.setLineDash([]);
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
        }

        function continueStroke(clientX, clientY) {
            if (!drawing) { return; }
            var p = toPos(clientX, clientY);
            ctx.lineTo(p.x, p.y);
            ctx.stroke();
        }

        function endStroke() { drawing = false; }

        function mdown(e) {
            e.preventDefault();
            beginStroke(e.clientX, e.clientY);
        }

        function mmove(e) {
            if (!drawing) { return; }
            e.preventDefault();
            continueStroke(e.clientX, e.clientY);
        }

        function tstart(e) {
            e.preventDefault();
            if (e.touches && e.touches.length) {
                beginStroke(e.touches[0].clientX, e.touches[0].clientY);
            }
        }

        function tmove(e) {
            if (!drawing) { return; }
            e.preventDefault();
            if (e.touches && e.touches.length) {
                continueStroke(e.touches[0].clientX, e.touches[0].clientY);
            }
        }

        canvas.addEventListener('touchstart', tstart, {passive: false});
        canvas.addEventListener('touchmove', tmove, {passive: false});
        canvas.addEventListener('touchend', endStroke, {passive: false});
        canvas.addEventListener('touchcancel', endStroke, {passive: false});
        canvas.addEventListener('mousedown', mdown);
        canvas.addEventListener('mousemove', mmove);
        canvas.addEventListener('mouseup', endStroke);
        canvas.addEventListener('mouseleave', endStroke);
        canvas.addEventListener('contextmenu', function (e) { e.preventDefault(); });

        if (clearBtn) {
            clearBtn.addEventListener('click', function (e) {
                e.preventDefault();
                ctx.setLineDash([]);
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                ink = false;
                input.value = '';
                placeholder();
            });
        }

        placeholder();

        return {
            hasInk: function () { return ink; },
            dataURL: function () { return ink ? canvas.toDataURL('image/png') : ''; }
        };
    }

    var consentCanvas = document.getElementById('obbs_sig_consent');
    var waiverCanvas = document.getElementById('obbs_sig_waiver');
    var consentInput = form.querySelector('input[name="consent_signature"]');
    var waiverInput = form.querySelector('input[name="waiver_signature"]');
    var sigConsent = initSigPad(consentCanvas, consentInput, document.getElementById('obbs_sig_clear_consent'));
    var sigWaiver = initSigPad(waiverCanvas, waiverInput, document.getElementById('obbs_sig_clear_waiver'));

    function collect() {
        var out = {};
        var els = form.querySelectorAll('input, select, textarea');
        for (var i = 0; i < els.length; i++) {
            var el = els[i];
            if (!el.name) { continue; }
            if (el.type === 'checkbox') { out[el.name] = el.checked ? '1' : ''; }
            else { out[el.name] = el.value; }
        }
        return out;
    }

    function saveDraft() {
        var save = collect();
        delete save.consent_signature;
        delete save.waiver_signature;
        try { localStorage.setItem(DRAFT_KEY, JSON.stringify(save)); } catch (e) {}
    }

    function restoreDraft() {
        var raw = null;
        try { raw = localStorage.getItem(DRAFT_KEY); } catch (e) { return; }
        if (!raw) { return; }
        var d = null;
        try { d = JSON.parse(raw); } catch (e) { return; }
        if (!d) { return; }
        var any = false;
        for (var k in d) {
            if (!Object.prototype.hasOwnProperty.call(d, k)) { continue; }
            var el = form.querySelector('[name="' + k + '"]');
            if (!el) { continue; }
            if (el.type === 'checkbox') { el.checked = (d[k] === '1' || d[k] === 'true' || d[k] === true); }
            else { el.value = d[k]; }
            any = true;
        }
        var bar = document.getElementById('obbs_draft_bar');
        bar.style.display = 'flex';
        if (!any) { bar.style.display = 'none'; }
    }

    function clearDraft() {
        try { localStorage.removeItem(DRAFT_KEY); } catch (e) {}
        window.location.reload();
    }

    form.addEventListener('input', saveDraft);
    form.addEventListener('change', saveDraft);

    nextBtn.addEventListener('click', function () {
        if (!validStep(index)) { return; }
        show(index + 1);
    });

    prevBtn.addEventListener('click', function () {
        show(index - 1);
    });

    form.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter' && ev.target.tagName === 'INPUT') {
            ev.preventDefault();
            if (index === steps.length - 1) { doSubmit(); }
            else { nextBtn.click(); }
        }
    });

    function showErrors(errors, step) {
        errorsList.innerHTML = '';
        for (var i = 0; i < errors.length; i++) {
            var li = document.createElement('li');
            li.appendChild(document.createTextNode(errors[i].msg));
            errorsList.appendChild(li);
        }
        errorsBox.style.display = 'block';
        show(step - 1);
        window.scrollTo(0, 0);
    }

    function doSubmit() {
        if (index !== steps.length - 1) { show(steps.length - 1); }
        if (!validStep(steps.length - 1)) { return; }
        if (!sigConsent.hasInk() || !sigWaiver.hasInk()) {
            showErrors([{step: 5, msg: 'Please draw your signature on both the Data Privacy Consent and the Waiver before submitting.'}], 5);
            return;
        }
        consentInput.value = sigConsent.dataURL();
        waiverInput.value = sigWaiver.dataURL();
        var payload = collect();
        var btn = submitBtn;
        btn.disabled = true;
        btn.innerHTML = 'Submitting&#8230;';
        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/intake-mobile/submit', true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onload = function () {
            btn.disabled = false;
            btn.innerHTML = 'Submit Intake Form';
            var res = null;
            try {
                var parsed = JSON.parse(xhr.responseText);
                res = (parsed && Object.prototype.hasOwnProperty.call(parsed, 'result')
                       && parsed.result !== undefined) ? parsed.result : parsed;
            } catch (e) {}
            if (xhr.status >= 200 && xhr.status < 300 && res) {
                if (res.ok) { onSuccess(res); }
                else { showErrors(res.errors || [], res.step || 1); }
            } else {
                onNetworkError();
            }
        };
        xhr.onerror = function () {
            btn.disabled = false;
            btn.innerHTML = 'Submit Intake Form';
            onNetworkError();
        };
        xhr.send(JSON.stringify(payload));
    }

    function onSuccess(res) {
        try { localStorage.removeItem(DRAFT_KEY); } catch (e) {}
        form.style.display = 'none';
        var t = document.getElementById('obbs_thanks');
        t.style.display = 'block';
        var has = document.getElementById('obbs_thanks_has');
        if (res.reference) {
            document.getElementById('obbs_thanks_name').textContent = res.name ? res.name : '';
            document.getElementById('obbs_thanks_ref').textContent = res.reference;
            has.style.display = 'block';
        } else {
            has.style.display = 'none';
        }
        window.scrollTo(0, 0);
    }

    function onNetworkError() {
        showErrors([{step: 1, msg: 'Could not reach the server. Please check your connection and try again - your draft is saved on this device.'}], index + 1);
    }

    submitBtn.addEventListener('click', doSubmit);
    document.getElementById('obbs_draft_clear').addEventListener('click', clearDraft);
    document.getElementById('obbs_new_intake').addEventListener('click', function () {
        window.location.href = '/intake-mobile';
    });

    restoreDraft();
    show(0);
})();
